const LANGUAGE_KEY = 'tmi-seller-language';
let activeLanguage = 'id';
try { if (localStorage.getItem(LANGUAGE_KEY) === 'en') activeLanguage = 'en'; } catch (_) { /* Optional storage. */ }
function uiLocale() { return activeLanguage === 'en' ? 'en-US' : 'id-ID'; }
function translate(text) {
  if (activeLanguage !== 'en' || typeof text !== 'string') return text;
  const value = text.trim();
  let translated = EN[value];
  if (translated === undefined) {
    const patterns = [
      [/^(\d)\/3 alat dijelajahi$/, (_, n) => `${n}/3 tools explored`],
      [/^Langkah (\d+)$/, (_, n) => `Step ${n}`],
      [/^Info (.+)$/, (_, label) => `About ${translate(label)}`],
      [/^Hapus (.+)$/, (_, id) => `Remove ${id}`],
      [/^(.+%) dari nilai barang setelah diskon$/, (_, n) => `${n} of discounted product value`],
      [/^Margin produk sebelum iklan: (.+)$/, (_, n) => `Product margin before ads: ${n}`],
      [/^Harga (.+) · HPP (.+) · target (.+)$/, (_, price, cost, target) => `Price ${price} · COGS ${cost} · target ${target}`],
      [/^([\d.,]+) hari$/, (_, n) => `${n} days`],
      [/^([\d.,]+) unit$/, (_, n) => `${n} units`]
    ];
    for (const [pattern, replacement] of patterns) {
      if (pattern.test(value)) { translated = value.replace(pattern, replacement); break; }
    }
  }
  return translated === undefined ? text : text.replace(value, () => translated);
}

// Preserve original text per DOM node so switching languages does not rebuild forms,
// close help disclosures, overwrite typed IDs, or change select option values.
const localizedNodes = new WeakMap();
const localizedAttributes = new WeakMap();
function localizeUI() {
  document.documentElement.lang = activeLanguage;
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  while (walker.nextNode()) {
    const node = walker.currentNode;
    if (!node.textContent.trim() || node.parentElement.closest('script,style,textarea,[data-no-i18n]')) continue;
    const previous = localizedNodes.get(node);
    const source = previous && node.textContent === previous.output ? previous.source : node.textContent;
    const output = translate(source);
    if (node.textContent !== output) node.textContent = output;
    localizedNodes.set(node, {source, output});
  }
  document.querySelectorAll('[aria-label],[placeholder],[alt],[title]').forEach(el => {
    if (el.closest('[data-no-i18n]')) return;
    const records = localizedAttributes.get(el) || {};
    for (const attr of ['aria-label','placeholder','alt','title']) {
      if (!el.hasAttribute(attr)) continue;
      const value = el.getAttribute(attr), previous = records[attr];
      const source = previous && value === previous.output ? previous.source : value;
      const output = translate(source);
      if (value !== output) el.setAttribute(attr, output);
      records[attr] = {source, output};
    }
    localizedAttributes.set(el, records);
  });
  document.title = typeof LABELS !== 'undefined' ? translate(LABELS[current]) + ' — TMI Seller Toolkit' : translate('Masuk ke Seller Toolkit');
  const select = document.querySelector('#language-select');
  if (select) select.value = activeLanguage;
}
function setLanguage(language) {
  if (!['id','en'].includes(language)) return;
  activeLanguage = language;
  try { localStorage.setItem(LANGUAGE_KEY, language); } catch (_) { /* Still switch for this visit. */ }
  if (typeof recalc === 'function') recalc();
  localizeUI();
}
function initializeLanguage() {
  // An option without a value derives its submitted value from its translated text.
  document.querySelectorAll('option:not([value])').forEach(option => option.setAttribute('value', option.textContent));
  document.querySelector('#language-select').addEventListener('change', event => setLanguage(event.target.value));
  localizeUI();
}
